{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h1",
        "intro_text",
        "framework_h2",
        "step1_card",
        "step2_card",
        "step3_card",
        "step4_card",
        "step5_card",
        "step6_card",
        "quick_actions_h2",
        "quick_action_button1",
        "quick_action_button2",
        "sources_h2",
        "source_button1",
        "source_button2"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Effective 1-on-1 Meetings with Direct Reports",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Regular and structured 1-on-1 meetings are crucial for building strong relationships, fostering growth, and ensuring alignment with your direct reports. This guide outlines a framework for effective 1-on-1s.",
        "variant": "body"
      },
      "children": []
    },
    "framework_h2": {
      "type": "Text",
      "props": {
        "text": "Framework for Effective 1-on-1s",
        "variant": "h2"
      },
      "children": []
    },
    "step1_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step1_title",
        "step1_desc"
      ]
    },
    "step1_title": {
      "type": "Text",
      "props": {
        "text": "1. Set a Clear Agenda",
        "variant": "h3"
      },
      "children": []
    },
    "step1_desc": {
      "type": "Text",
      "props": {
        "text": "Encourage your direct report to set the agenda. This empowers them to bring up topics most important to them, ensuring the meeting addresses their needs and concerns.",
        "variant": "body"
      },
      "children": []
    },
    "step2_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step2_title",
        "step2_desc"
      ]
    },
    "step2_title": {
      "type": "Text",
      "props": {
        "text": "2. Listen Actively",
        "variant": "h3"
      },
      "children": []
    },
    "step2_desc": {
      "type": "Text",
      "props": {
        "text": "Focus on listening more than talking. Ask open-ended questions and allow for silence, giving your report space to think and elaborate.",
        "variant": "body"
      },
      "children": []
    },
    "step3_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step3_title",
        "step3_desc"
      ]
    },
    "step3_title": {
      "type": "Text",
      "props": {
        "text": "3. Focus on the Direct Report's Growth",
        "variant": "h3"
      },
      "children": []
    },
    "step3_desc": {
      "type": "Text",
      "props": {
        "text": "Discuss career aspirations, skill development, and opportunities for advancement. Help them identify goals and create a plan for achieving them.",
        "variant": "body"
      },
      "children": []
    },
    "step4_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step4_title",
        "step4_desc"
      ]
    },
    "step4_title": {
      "type": "Text",
      "props": {
        "text": "4. Provide Constructive Feedback",
        "variant": "h3"
      },
      "children": []
    },
    "step4_desc": {
      "type": "Text",
      "props": {
        "text": "Offer specific, actionable feedback on performance, both positive and areas for improvement. Ensure it's delivered with empathy and a focus on development.",
        "variant": "body"
      },
      "children": []
    },
    "step5_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step5_title",
        "step5_desc"
      ]
    },
    "step5_title": {
      "type": "Text",
      "props": {
        "text": "5. Document Key Discussions and Actions",
        "variant": "h3"
      },
      "children": []
    },
    "step5_desc": {
      "type": "Text",
      "props": {
        "text": "Keep brief notes on topics discussed, decisions made, and action items. This helps track progress and ensures accountability for both parties.",
        "variant": "body"
      },
      "children": []
    },
    "step6_card": {
      "type": "Card",
      "props": {},
      "children": [
        "step6_title",
        "step6_desc"
      ]
    },
    "step6_title": {
      "type": "Text",
      "props": {
        "text": "6. Follow Up on Commitments",
        "variant": "h3"
      },
      "children": []
    },
    "step6_desc": {
      "type": "Text",
      "props": {
        "text": "Before the next 1-on-1, review previous action items. This demonstrates your commitment and reinforces the importance of the meetings.",
        "variant": "body"
      },
      "children": []
    },
    "quick_actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_action_button1": {
      "type": "Button",
      "props": {
        "label": "Download 1-on-1 Template"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/1on1-template"
          }
        }
      }
    },
    "quick_action_button2": {
      "type": "Button",
      "props": {
        "label": "Schedule a Meeting"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/schedule-meeting"
          }
        }
      }
    },
    "sources_h2": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "source_button1": {
      "type": "Button",
      "props": {
        "label": "Article: The Art of the 1-on-1"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/article-the-art-of-1on1"
          }
        }
      }
    },
    "source_button2": {
      "type": "Button",
      "props": {
        "label": "Book: Radical Candor"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/book-radical-candor"
          }
        }
      }
    }
  }
}
